def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each prefix of the necklace
    prefix_energies = {}
    prefix_energies[0] = 0

    # Iterate over the beads and calculate the maximum energy for each prefix
    for i in range(len(beads)):
        # The maximum energy for a prefix that ends at the current bead is the maximum of:
        # 1. The maximum energy for the previous prefix plus the energy released by merging the previous bead with the current bead
        # 2. The maximum energy for the previous prefix
        prefix_energies[i] = max(prefix_energies[i-1] + beads[i-1] * beads[i], prefix_energies[i-1])

    # The maximum energy for the entire necklace is the maximum energy for any prefix
    return max(prefix_energies.values())

